def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out"""
    # Simple approach: find first differing position and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            # Insertion at end
            return (s_in[-1] if s_in else "", s_out[pos:], pos) if pos >= 0 else ("", s_out, len(s_in))
        else:
            # Deletion at end  
            return (s_in[pos:], "", pos) if pos >= 0 else (s_in, "", len(s_in))

    # Find what was replaced
    old_sub = ""
    new_sub = ""

    # Check if we're replacing a substring
    max_len = min(3, len(s_in), len(s_out))
    for l in range(max_len, 0, -1):
        if pos + l <= len(s_in) and pos + l <= len(s_out):
            old_part = s_in[pos:pos+l]
            new_part = s_out[pos:pos+l]
            if old_part != new_part:
                old_sub = old_part
                new_sub = new_part
                break

    if not old_sub:
        # Simple character replacement or insertion/deletion
        old_sub = s_in[pos:pos+1] if pos < len(s_in) else ""
        new_sub = s_out[pos:pos+1] if pos < len(s_out) else ""

    return (old_sub, new_sub, pos)

def propose_rule_candidates(s_in, s_out):
    """Generate candidate replacement rules from a change"""
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Return specific rule first, then more general ones
    candidates = []

    # Most specific: exact match
    candidates.append((old_sub, new_sub))

    # Generalize by removing characters from pattern if possible
    if len(old_sub) > 1:
        # Try removing first char
        if len(old_sub) > 1:
            candidates.append((old_sub[1:], new_sub))
        # Try removing last char  
        if len(old_sub) > 1:
            candidates.append((old_sub[:-1], new_sub))

    return candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings"""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules perform on the input/output set"""
    predicted = apply_rules(inputs, rules)
    correct = sum(1 for p, o in zip(predicted, outputs) if p == o)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find which examples are incorrectly modified by rules"""
    predicted = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, pred) in enumerate(zip(inputs, outputs, predicted)):
        if pred != outp and inp != outp:  # Only report if original was different and prediction is wrong
            over_apps.append((i, inp, pred))
    return over_apps

# Now let's analyze our problem
inputs = ['awkydv', 'zw', 'zvy', 'kxgkca', 'ybc']
outputs = ['xwwxwgkyaydbvk', 'hiw', 'hibvky', 'xwgkyaxgxwgkyakyaxw', 'ybkya']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:")
for idx, inp, outp in changed:
    print(f"  {idx}: '{inp}' -> '{outp}'")

print("\nAnalyzing each change:")
for idx, inp, outp in changed:
    print(f"\nChange {idx}: '{inp}' -> '{outp}'")
    old_sub, new_sub, pos = find_minimal_edit(inp, outp)
    print(f"  Minimal edit: '{old_sub}' -> '{new_sub}' at position {pos}")
    candidates = propose_rule_candidates(inp, outp)
    print(f"  Candidates: {candidates}")

